import{c as n,U as t,j as i,g as a,o as l,a6 as p,n as o}from"./chunks/framework.h4W4t1IS.js";const b=JSON.parse('{"title":"Organisation des classes","description":"","frontmatter":{"title":"Organisation des classes","status":"ready","tags":["qualite","all","packages"],"authors":["Jean-François Dion"],"reviewers":[]},"headers":[],"relativePath":"qualite/packages/packages.md","filePath":"qualite/packages/packages.md"}'),c={name:"qualite/packages/packages.md"},r={id:"frontmatter-title",tabindex:"-1"};function d(s,e,u,m,h,g){return t(),i("div",null,[a("h1",r,[l(p(s.$frontmatter.title)+" ",1),e[0]||(e[0]=a("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":'Permalink to "{{ $frontmatter.title }}"'},"​",-1))]),e[1]||(e[1]=o(`<p>Les <strong>packages</strong> Java regroupent les classes dans une hiérarchie logique. Une bonne organisation révèle l&#39;intention de l&#39;application et facilite la navigation.</p><h2 id="objectifs-d-apprentissage" tabindex="-1">Objectifs d&#39;apprentissage <a class="header-anchor" href="#objectifs-d-apprentissage" aria-label="Permalink to &quot;Objectifs d&#39;apprentissage&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Après cette section, tu seras capable de...</p><ul><li>Appliquer les principes <a href="/420-w30-sf-po2/lexique.html#principe-de-fermeture-commune" class="lexicon-link" title="Principe de conception qui stipule que les classes qui changent pour les mêmes raisons devraient être regroupées dans le même module ou package.">CCP</a> et <a href="/420-w30-sf-po2/lexique.html#principe-de-reutilisation-commune" class="lexicon-link" title="Principe de conception qui stipule que les classes qui sont utilisées ensemble devraient être regroupées dans le même module ou package.">CRP</a> pour organiser les packages</li><li>Comparer l&#39;organisation par couches et par fonctionnalité</li><li>Éviter les dépendances circulaires entre packages</li><li>Reconnaître une structure de packages qui « crie » l&#39;intention de l&#39;application</li></ul></div><h2 id="principes-directeurs" tabindex="-1">Principes directeurs <a class="header-anchor" href="#principes-directeurs" aria-label="Permalink to &quot;Principes directeurs&quot;">​</a></h2><p>Principes tirés de <em><a href="/420-w30-sf-po2/lexique.html#code-propre" class="lexicon-link" title="Code qui est lisible, compréhensible et maintenable. Il suit des conventions de nommage, des principes de conception et évite la duplication et la complexité inutile.">Clean Code</a></em>.</p><h3 id="ccp-principe-de-fermeture-commune" tabindex="-1">CCP - Principe de fermeture commune <a class="header-anchor" href="#ccp-principe-de-fermeture-commune" aria-label="Permalink to &quot;CCP - Principe de fermeture commune&quot;">​</a></h3><blockquote><p>Les classes qui changent ensemble sont regroupées dans le même package.</p></blockquote><p>Si plusieurs classes sont modifiées ensemble lors d&#39;une même fonctionnalité, elles devraient se trouver dans le même package.</p><h3 id="crp-principe-de-reutilisation-commune" tabindex="-1">CRP - Principe de réutilisation commune <a class="header-anchor" href="#crp-principe-de-reutilisation-commune" aria-label="Permalink to &quot;CRP - Principe de réutilisation commune&quot;">​</a></h3><blockquote><p>Les classes qui sont utilisées ensemble sont regroupées dans le même package.</p></blockquote><p>Les clients d&#39;un package utilisent généralement toutes les classes du package. Éviter d&#39;y mettre des classes non liées.</p><h2 id="packages" tabindex="-1">Packages <a class="header-anchor" href="#packages" aria-label="Permalink to &quot;Packages&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>com.boutique.ecommerce</span></span>
<span class="line"><span>├── produit                     // domaine de produits</span></span>
<span class="line"><span>│   ├── Produit.java</span></span>
<span class="line"><span>│   ├── ProduitController.java</span></span>
<span class="line"><span>│   ├── ProduitService.java</span></span>
<span class="line"><span>│   ├── ProduitRepository.java</span></span>
<span class="line"><span>│   └── ProduitDTO.java</span></span>
<span class="line"><span>├── panier                      // domaine du panier d&#39;achat</span></span>
<span class="line"><span>│   ├── Panier.java</span></span>
<span class="line"><span>│   ├── PanierArticle.java</span></span>
<span class="line"><span>│   └── PanierService.java</span></span>
<span class="line"><span>├── commande                    // domaine des commandes</span></span>
<span class="line"><span>│   ├── Commande.java</span></span>
<span class="line"><span>│   ├── CommandeService.java</span></span>
<span class="line"><span>│   └── paiement                // sous-domaine de paiement</span></span>
<span class="line"><span>│       ├── TraitementPaiement.java</span></span>
<span class="line"><span>│       └── PortailPaiement.java</span></span>
<span class="line"><span>└── commun                      // composantes partagées</span></span>
<span class="line"><span>    ├── exception</span></span>
<span class="line"><span>    │   ├── ResourceIntrouvableException.java</span></span>
<span class="line"><span>    │   └── DomaineException.java</span></span>
<span class="line"><span>    └── config</span></span>
<span class="line"><span>        └── AppConfig.java</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Screaming architecture</p><p>Les packages doivent présenter clairement la fonction de l’application. Ce qu’elle fait, pas comment elle est construite</p></div><h2 id="aide-a-la-decision-pour-la-constitution-des-packages" tabindex="-1">Aide à la décision pour la constitution des packages <a class="header-anchor" href="#aide-a-la-decision-pour-la-constitution-des-packages" aria-label="Permalink to &quot;Aide à la décision pour la constitution des packages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Règle</th><th>Description</th></tr></thead><tbody><tr><td>Groupement logique</td><td>Les classes liées sont regroupées dans le même package</td></tr><tr><td>Navigation intuitive</td><td>La structure des packages facilite la localisation des classes et des fonctionnalités</td></tr><tr><td>Un package = une responsabilité</td><td>Le rôle doit se décrire en une phrase</td></tr><tr><td>Haute <a href="/420-w30-sf-po2/lexique.html#cohesion" class="lexicon-link" title="Degré auquel les éléments d&#39;un module ou d&#39;une classe sont liés et travaillent ensemble pour accomplir une tâche spécifique. Une forte cohésion est souhaitable pour la clarté et la réutilisabilité du code.">cohésion</a></td><td>Les classes d&#39;un package sont fortement liées</td></tr><tr><td>Faible <a href="/420-w30-sf-po2/lexique.html#couplage" class="lexicon-link" title="Degré de dépendance entre différentes parties d&#39;un système. Un couplage faible est souhaitable pour faciliter la maintenance et l&#39;évolution du code.">couplage</a></td><td>Dépendances entre packages minimales</td></tr><tr><td>Profondeur raisonnable</td><td>Maximum 4-5 niveaux</td></tr><tr><td>Pas de cycles</td><td>Les packages ne forment pas de boucles de dépendances</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Cycles de dépendances</p><p>Si le package <code>A</code> dépend de <code>B</code> et <code>B</code> dépend de <code>A</code>, on a une <a href="/420-w30-sf-po2/lexique.html#dependance-circulaire" class="lexicon-link" title="Deux packages (ou classes) qui dépendent l&#39;un de l&#39;autre mutuellement. Brise la compilation et les tests en isolation; se règle en introduisant une interface ou un package partagé (DIP).">dépendance circulaire</a>. Cela empêche de compiler ou de tester les packages séparément.</p></div><h2 id="separation-en-couches" tabindex="-1">Séparation en couches <a class="header-anchor" href="#separation-en-couches" aria-label="Permalink to &quot;Séparation en couches&quot;">​</a></h2><p>Toutes les applications sont découpables en couches techniques telles que domaine, présentation, persistance.</p><p>Les couches les plus fréquentes sont:</p><table tabindex="0"><thead><tr><th>Couche</th><th>Fonction</th></tr></thead><tbody><tr><td>Présentation</td><td><a href="/420-w30-sf-po2/lexique.html#interface" class="lexicon-link" title="Contrat qui définit un ensemble de méthodes qu&#39;une classe doit implémenter, sans fournir d&#39;implémentation concrète. Permet de définir des comportements communs pour différentes classes.">Interface</a> graphique, sortie en console, HTML, etc.</td></tr><tr><td>Application</td><td>Couche d&#39;orchestration entre le code de l&#39;application et le code des librairies externes / frameworks</td></tr><tr><td>Service</td><td>Couche d&#39;orchestration du domaine (<a href="/420-w30-sf-po2/lexique.html#entite" class="lexicon-link" title="Objet qui représente un concept ou un élément du domaine d&#39;affaire, généralement identifiable par un identifiant unique et ayant une identité propre.">entités</a> entre elles)</td></tr><tr><td>Domaine</td><td>Entités, ValueObjects, contrats pour les repositories, etc.</td></tr><tr><td>Infrastructure</td><td>Couche technique pour la communication externe / stockage</td></tr></tbody></table><p>En reprennant la structure de commerce en ligne, on peut subdiviser les domaines en couches techniques.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>com.boutique.ecommerce</span></span>
<span class="line"><span>├── produit                           // domaine de produits</span></span>
<span class="line"><span>│   ├── domaine</span></span>
<span class="line"><span>│   │   ├── Produit.java</span></span>
<span class="line"><span>│   │   ├── exception</span></span>
<span class="line"><span>│   │   │   └── ProduitInvalideException.java</span></span>
<span class="line"><span>│   │   ├── ProduitService.java  // peut être inclu dans le domaine ou dans son propre package</span></span>
<span class="line"><span>│   │   └── ProduitRepository.java</span></span>
<span class="line"><span>│   ├── controller</span></span>
<span class="line"><span>│   │   └── ProduitController.java</span></span>
<span class="line"><span>│   ├── infrastructure</span></span>
<span class="line"><span>│   │   └── ProduitRepositoryEnMemoire.java</span></span>
<span class="line"><span>│   └── ProduitDTO.java</span></span>
<span class="line"><span>├── ...</span></span></code></pre></div>`,23))])}const k=n(c,[["render",d]]);export{b as __pageData,k as default};
